import { Collapsible, CollapsiblePanel, CollapsibleTrigger, cn } from '@gntik-ai/ui';
import { useEffect, useRef, useState, type ReactNode, type Ref } from 'react';
import { Markdown } from '../markdown';
import { formatElapsed } from '../utils/formatElapsed';
import { useChatI18n } from '../utils/i18n';
import { reasoningBlockStyles as s } from './reasoningBlock.variants';

export interface ReasoningBlockProps {
  children?: string | ReactNode;
  streaming?: boolean;
  durationMs?: number;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  label?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

/** A quiet disclosure for reasoning tokens; announcements belong in ChatAnnouncer. */
export function ReasoningBlock({
  children,
  streaming = false,
  durationMs,
  open,
  defaultOpen = false,
  onOpenChange,
  label,
  className,
  ref,
}: ReasoningBlockProps) {
  const { tc } = useChatI18n();
  const [internalOpen, setInternalOpen] = useState(streaming || defaultOpen);
  const wasStreaming = useRef(streaming);
  const userToggled = useRef(false);

  useEffect(() => {
    if (wasStreaming.current === streaming) return;
    wasStreaming.current = streaming;
    if (streaming) userToggled.current = false;
    if (open === undefined && (streaming || !userToggled.current)) {
      // Synchronise only a stream phase transition, never a token or defaultOpen update.
      setInternalOpen(streaming || defaultOpen);
    }
  }, [streaming, defaultOpen, open]);

  const hasContent =
    typeof children === 'string' ? children.trim().length > 0 : children != null && typeof children !== 'boolean';
  if (!streaming && !hasContent) return null;

  return (
    <Collapsible
      ref={ref}
      open={open ?? internalOpen}
      onOpenChange={(next) => {
        if (streaming) userToggled.current = true;
        if (open === undefined) setInternalOpen(next);
        onOpenChange?.(next);
      }}
      className={cn(s.root, className)}
    >
      <CollapsibleTrigger className={s.trigger} {...(!hasContent ? { 'aria-controls': undefined } : {})}>
        <span className={streaming ? s.running : undefined}>
          {label ??
            (streaming
              ? tc('chat.thinking')
              : durationMs !== undefined
                ? tc('chat.thoughtFor', { duration: formatElapsed(durationMs) })
                : tc('chat.reasoning'))}
        </span>
      </CollapsibleTrigger>
      {hasContent && (
        <CollapsiblePanel aria-busy={streaming}>
          <div className={s.body}>
            {typeof children === 'string' ? (
              <Markdown streaming={streaming} className={s.markdown}>
                {children}
              </Markdown>
            ) : (
              children
            )}
          </div>
        </CollapsiblePanel>
      )}
    </Collapsible>
  );
}

export { ReasoningBlock, type ReasoningBlockProps } from './ReasoningBlock';
export { reasoningBlockStyles } from './reasoningBlock.variants';
export { doc as reasoningBlockDoc } from './ReasoningBlock.doc';

import { toolCallCardStyles } from '../tool-call-card/toolCallCard.variants';

export const reasoningBlockStyles = {
  root: toolCallCardStyles.root,
  trigger: toolCallCardStyles.trigger,
  running: 'animate-pulse motion-reduce:animate-none',
  markdown: 'text-[13px] text-muted-foreground',
  body: 'border-s border-border ps-3 text-[13px] text-muted-foreground',
} as const;

/** Whole-second reasoning duration, kept separate from ToolCallCard's precision. */
export function formatElapsed(ms: number): string {
  const seconds = Math.round(ms / 1000);
  if (seconds < 60) return `${seconds} s`;
  return `${Math.floor(seconds / 60)} m ${String(seconds % 60).padStart(2, '0')} s`;
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'ReasoningBlock',
  group: 'Display',
  status: 'beta',
  description:
    'A collapsible reasoning trace above an assistant answer. Opens while streaming, then settles once to defaultOpen unless the reader toggles it. Controlled open always wins. Strings use safe streaming Markdown; other nodes render as provided. Pass durationMs for whole-second elapsed labels, or label to override. Empty completed traces render nothing. Use ChatAnnouncer reasoning for the thinking phase; the trace itself has no live region.',
  primitive: '@base-ui/react/collapsible',
  pattern: 'disclosure',
  keyboard: [
    ['Enter', 'Expands or collapses the reasoning trace'],
    ['Space', 'Expands or collapses the reasoning trace'],
    ['Tab', 'Moves to links and controls in the open panel'],
  ],
  tokens: ['card', 'border', 'secondary', 'muted-foreground', 'focus-ring'],
};
